import zipfile, xml.etree.ElementTree as ET, json, re

path = '/sessions/local_7q6404zik6/mnt/uploads/sample_model.xlsx'
NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
}

with zipfile.ZipFile(path) as z:
    # Get shared strings
    shared_strings = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss_tree = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_tree.findall('main:si', NS):
            t = si.find('main:t', NS)
            if t is not None:
                shared_strings.append(t.text or '')
            else:
                # Rich text - concatenate all t elements
                texts = [e.text or '' for e in si.findall('.//main:t', NS)]
                shared_strings.append(''.join(texts))

    # Get workbook sheet names
    wb_tree = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sheet in wb_tree.findall('.//main:sheet', NS):
        sheets.append({'name': sheet.get('name'), 'id': sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')})
    print("Sheets:", [s['name'] for s in sheets])

    # Get rels to map rId -> sheet file
    rels_tree = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rels = {}
    for rel in rels_tree:
        rels[rel.get('Id')] = rel.get('Target')

    # Parse each sheet
    all_sheets = {}
    for sheet in sheets:
        rid = sheet['id']
        target = rels.get(rid, '')
        if not target.startswith('worksheets/'):
            target = 'worksheets/' + target.split('worksheets/')[-1]
        fname = f'xl/{target}'
        if fname not in z.namelist():
            print(f"Missing: {fname}")
            continue
        ws_tree = ET.fromstring(z.read(fname))
        rows_data = {}
        for row in ws_tree.findall('.//main:row', NS):
            row_num = int(row.get('r', 0))
            row_cells = {}
            for cell in row.findall('main:c', NS):
                ref = cell.get('r', '')
                col = re.sub(r'\d', '', ref)
                t = cell.get('t', '')
                v_el = cell.find('main:v', NS)
                if v_el is None:
                    val = None
                elif t == 's':
                    idx = int(v_el.text)
                    val = shared_strings[idx] if idx < len(shared_strings) else f'<ss:{idx}>'
                else:
                    try:
                        val = float(v_el.text) if '.' in (v_el.text or '') else int(v_el.text)
                    except:
                        val = v_el.text
                row_cells[col] = val
            rows_data[row_num] = row_cells
        all_sheets[sheet['name']] = rows_data

    # Print first 40 rows of each sheet
    for sheet_name, rows in all_sheets.items():
        print(f"\n=== SHEET: {sheet_name} ===")
        for r in sorted(rows.keys())[:60]:
            if rows[r]:
                print(f"  Row {r}: {dict(sorted(rows[r].items()))}")

